<?php
namespace App\Http\Controllers;
use App\Models\User;use Illuminate\Auth\Events\PasswordReset;use Illuminate\Http\Request;use Illuminate\Support\Facades\Hash;use Illuminate\Support\Facades\Password;use Illuminate\Support\Str;use Illuminate\Validation\Rules;
class PasswordResetController {public function request(){return view('forgot-password');}public function email(Request $request){$request->validate(['email'=>'required|email']);$status=Password::sendResetLink($request->only('email'));return $status===Password::RESET_LINK_SENT?back()->with('success',__($status)):back()->withErrors(['email'=>__($status)]);}public function reset(Request $request,string $token){return view('reset-password',['token'=>$token,'email'=>$request->query('email')]);}public function update(Request $request){$request->validate(['token'=>'required','email'=>'required|email','password'=>['required','confirmed',Rules\Password::min(12)]]);$status=Password::reset($request->only('email','password','password_confirmation','token'),function(User $user,string $password){$user->forceFill(['password'=>Hash::make($password),'remember_token'=>Str::random(60)])->save();event(new PasswordReset($user));});return $status===Password::PASSWORD_RESET?redirect('/login')->with('success',__($status)):back()->withErrors(['email'=>__($status)]);}}
